package org.simpleweather.app;

import android.app.*;
import android.content.*;
import android.graphics.Typeface;
import android.view.*;
import android.widget.*;
import android.text.InputType;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;

/** Original native weekly timetable, inspired by the reference project's feature layout. */
final class ScheduleScreen {
    private final MainActivity a;
    private final android.content.SharedPreferences prefs;
    private ScheduleModel model;
    private int selectedWeek;
    static String[] days(){return new String[]{UiText.get("schedule_001"),UiText.get("schedule_002"),UiText.get("schedule_003"),UiText.get("schedule_004"),UiText.get("schedule_005"),UiText.get("schedule_006"),UiText.get("schedule_007")};}
    ScheduleScreen(MainActivity activity){a=activity;prefs=a.getSharedPreferences("timetable",0);String raw=prefs.getString("data","");try{model=raw.isEmpty()?new ScheduleModel():ScheduleModel.parse(raw);}catch(Exception e){prefs.edit().putString("unreadable_backup",raw).apply();model=new ScheduleModel();a.toast(UiText.get("schedule_008"));}selectedWeek=Math.min(model.weeks,Math.max(1,model.week(LocalDate.now())));}
    private void save(){try{prefs.edit().putString("data",model.json().toString()).apply();}catch(Exception e){a.toast(UiText.get("background_crop_010"));}}
    void addCourse(){edit(null);}
    void render(){

        int current=model.week(LocalDate.now());String semesterStatus=current<1?UiText.get("schedule_009"):current>model.weeks?UiText.get("schedule_010"):UiText.get("schedule_011")+current+UiText.get("schedule_model_017");
        a.body.addView(a.text(semesterStatus+UiText.get("schedule_012"),12,a.MUTED,false));a.gap(a.body,12);
        LinearLayout nav=a.row();nav.addView(a.button("‹",false,()->{if(selectedWeek>1){selectedWeek--;a.switchTab(1);}}),a.lp(48,48));a.gapHorizontal(nav,8);TextView week=a.button(UiText.get("schedule_model_018")+selectedWeek+" / "+model.weeks+UiText.get("schedule_model_017"),false,this::selectWeek);nav.addView(week,new LinearLayout.LayoutParams(0,-2,1));a.gapHorizontal(nav,8);nav.addView(a.button("›",false,()->{if(selectedWeek<model.weeks){selectedWeek++;a.switchTab(1);}}),a.lp(48,48));a.body.addView(nav);a.gap(a.body,10);
        LocalDate monday=model.semester.plusWeeks(selectedWeek-1);a.body.addView(a.text(monday+UiText.get("schedule_013")+monday.plusDays(6),12,a.MUTED,false));a.gap(a.body,16);
        today(current);a.gap(a.body,16);grid(monday);a.gap(a.body,16);a.body.addView(a.text(UiText.get("schedule_014"),17,a.TITLE,true));a.gap(a.body,12);
        if(model.courses.isEmpty()){LinearLayout empty=a.card();empty.addView(a.text(UiText.get("schedule_015"),17,a.TITLE,true));a.gap(empty,10);empty.addView(a.text(UiText.get("schedule_016"),13,a.MUTED,false));a.gap(empty,12);empty.addView(a.button(UiText.get("action_add_course"),true,()->edit(null)));}
        List<ScheduleModel.Course> sorted=new ArrayList<>(model.courses);sorted.sort(Comparator.comparingInt((ScheduleModel.Course c)->c.day).thenComparingInt(c->c.first).thenComparingInt(c->c.weekStart));
        for(ScheduleModel.Course c:sorted){LinearLayout card=a.card();card.setBackground(a.shape(ThemeColors.pale(c.seedColor()),18));card.addView(a.text(nameText(c),18,a.TITLE,true));a.gap(card,8);card.addView(a.text(days()[c.day-1]+UiText.get("schedule_017")+c.first+"–"+c.last+UiText.get("schedule_018")+model.courseTime(c),13,a.INK,false));a.gap(card,7);card.addView(a.text(roomText(c)+"\n"+teacherText(c)+"\n"+model.weekLabel(c),13,a.MUTED,false));a.tap(card,ThemeColors.pale(c.seedColor()),18,()->edit(c));a.gap(a.body,10);}

    }
    private void today(int week){LinearLayout c=a.card();c.addView(a.text(UiText.get("schedule_019")+days()[LocalDate.now().getDayOfWeek().getValue()-1],17,a.TITLE,true));a.gap(c,12);int n=0;for(ScheduleModel.Course course:model.courses)if(course.day==LocalDate.now().getDayOfWeek().getValue()&&course.runs(week)){c.addView(a.text(model.courseTime(course)+"  "+nameText(course)+"  "+roomText(course)+"  "+teacherText(course),13,a.INK,false));a.gap(c,7);n++;}if(n==0)c.addView(a.text(UiText.get("schedule_020"),13,a.MUTED,false));}
    private void selectWeek(){LinearLayout c=form();EditText input=field(c,UiText.get("schedule_021")+model.weeks+UiText.get("earthquake_api_004"),String.valueOf(selectedWeek),true);AlertDialog dialog=new ToolDialog(a).setTitle(UiText.get("schedule_022")).setView(c).setPositiveButton(UiText.get("numeric_inputs_004"),null).setNegativeButton(UiText.get("action_cancel"),null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{try{int week=Integer.parseInt(input.getText().toString().trim());if(week<1||week>model.weeks)throw new NumberFormatException();selectedWeek=week;dialog.dismiss();a.switchTab(1);}catch(NumberFormatException e){input.setError(UiText.get("schedule_023")+model.weeks+UiText.get("schedule_024"));}}));dialog.show();}
    private void grid(LocalDate monday){
        LinearLayout c=a.card();c.addView(a.text(UiText.get("schedule_025"),17,a.TITLE,true));a.gap(c,12);HorizontalScrollView scroll=new HorizontalScrollView(a);LinearLayout grid=a.column();int label=58,width=112,height=126;
        LinearLayout heading=a.row();heading.addView(a.text(UiText.get("schedule_026"),12,a.MUTED,true),a.lp(label,48));for(int day=1;day<=7;day++){LocalDate date=monday.plusDays(day-1);TextView t=a.text(days()[day-1]+"\n"+date.format(DateTimeFormatter.ofPattern("M/d")),12,date.equals(LocalDate.now())?a.BLUE:a.INK,true);t.setGravity(Gravity.CENTER);heading.addView(t,a.lp(width,48));}grid.addView(heading);
        FrameLayout matrix=new FrameLayout(a);matrix.setLayoutParams(a.lp(label+7*width,model.slots.size()*height));
        for(int i=0;i<model.slots.size();i++){
            ScheduleModel.Slot slot=model.slots.get(i);TextView time=a.text((i+1)+"\n"+slot.start+"\n"+slot.end,11,a.MUTED,false);time.setGravity(Gravity.CENTER);FrameLayout.LayoutParams timeLp=new FrameLayout.LayoutParams(a.dp(label),a.dp(height));timeLp.topMargin=a.dp(i*height);matrix.addView(time,timeLp);
            for(int day=0;day<7;day++){View cell=new View(a);cell.setBackground(a.shape(0xFFF5F7FB,10));FrameLayout.LayoutParams cellLp=new FrameLayout.LayoutParams(a.dp(width-4),a.dp(height-4));cellLp.leftMargin=a.dp(label+day*width);cellLp.topMargin=a.dp(i*height);matrix.addView(cell,cellLp);}
        }
        for(ScheduleModel.Course course:model.courses)if(course.runs(selectedWeek)){
            TextView block=a.text(nameText(course)+(course.room.isEmpty()?"":"\n"+roomText(course))+(course.teacher.isEmpty()?"":"\n"+teacherText(course)),12,a.INK,true);block.setPadding(a.dp(7),a.dp(8),a.dp(7),a.dp(6));block.setMaxLines(Math.max(6,(course.last-course.first+1)*7));block.setEllipsize(android.text.TextUtils.TruncateAt.END);a.tap(block,ThemeColors.pale(course.seedColor()),10,()->edit(course));FrameLayout.LayoutParams p=new FrameLayout.LayoutParams(a.dp(width-4),a.dp((course.last-course.first+1)*height-4));p.leftMargin=a.dp(label+(course.day-1)*width);p.topMargin=a.dp((course.first-1)*height);matrix.addView(block,p);
        }
        grid.addView(matrix);scroll.addView(grid);c.addView(scroll);
    }
    void resetSettings(){model.resetSettings();selectedWeek=1;save();}
    void menu(){LinearLayout c=form();c.addView(a.button(UiText.get("schedule_027"),false,this::semester));a.gap(c,10);c.addView(a.button(UiText.get("schedule_028"),false,this::times));a.gap(c,10);c.addView(a.button(UiText.get("schedule_029"),false,this::prefixes));new ToolDialog(a).setTitle(UiText.get("schedule_030")).setView(scroll(c)).setNegativeButton(UiText.get("action_back"),null).show();}
    private String nameText(ScheduleModel.Course c){return (a.preferences.getBoolean("course_name_prefix",true)?UiText.get("schedule_031"):"")+c.name;}
    private String roomText(ScheduleModel.Course c){int p=a.preferences.getInt("course_room_prefix",1);return (p==0?"@":p==1?UiText.get("schedule_032"):"")+(c.room.isEmpty()?UiText.get("schedule_033"):c.room);}
    private String teacherText(ScheduleModel.Course c){return (a.preferences.getBoolean("course_teacher_prefix",true)?UiText.get("schedule_034"):"")+(c.teacher.isEmpty()?UiText.get("schedule_033"):c.teacher);}
    private void prefixes(){LinearLayout c=form();String[] names={UiText.get("schedule_035"),UiText.get("schedule_036"),UiText.get("schedule_037")};for(int n=0;n<names.length;n++){final int id=n;c.addView(a.button(names[n],false,()->prefixChoice(id)));a.gap(c,10);}new ToolDialog(a).setTitle(UiText.get("schedule_029")).setView(c).setNegativeButton(UiText.get("action_back"),null).show();}
    private void prefixChoice(int n){
        String[] options=n==0?new String[]{UiText.get("schedule_038"),UiText.get("schedule_039"),UiText.get("schedule_040")}:n==1?new String[]{UiText.get("schedule_041"),UiText.get("schedule_040")}:new String[]{UiText.get("schedule_042"),UiText.get("schedule_040")};
        int saved=n==0?a.preferences.getInt("course_room_prefix",1):0;int selected=n==0?(saved==1?0:saved==0?1:2):(a.preferences.getBoolean(n==1?"course_name_prefix":"course_teacher_prefix",true)?0:1);
        new ToolDialog(a).setTitle(n==0?UiText.get("schedule_035"):n==1?UiText.get("schedule_036"):UiText.get("schedule_037")).setSingleChoiceItems(options,selected,(x,p)->{if(n==0)a.preferences.edit().putInt("course_room_prefix",p==0?1:p==1?0:2).apply();else a.preferences.edit().putBoolean(n==1?"course_name_prefix":"course_teacher_prefix",p==0).apply();a.refreshScreen();}).setNegativeButton(UiText.get("action_back"),null).show();
    }
    private EditText field(LinearLayout parent,String label,String value,boolean number){parent.addView(a.text(label,13,a.MUTED,false));EditText t=new EditText(a);t.setContentDescription(label);t.setText(value);t.setTextSize(16);t.setSingleLine(true);t.setPadding(a.dp(14),a.dp(6),a.dp(14),a.dp(6));t.setInputType(number?InputType.TYPE_CLASS_NUMBER:InputType.TYPE_CLASS_TEXT);t.setSelectAllOnFocus(true);t.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(number?3:80)});parent.addView(t,a.lp(-1,52));a.gap(parent,10);return t;}
    private Spinner spinner(LinearLayout c,String title,String[] labels,int selected){c.addView(a.text(title,13,a.MUTED,false));Spinner s=new Spinner(a);ArrayAdapter<String> adapter=new ChoiceAdapter(a,labels);s.setAdapter(adapter);s.setSelection(Math.max(0,Math.min(labels.length-1,selected)));c.addView(s,a.lp(-1,52));a.gap(c,10);return s;}
    private LinearLayout form(){LinearLayout c=a.column();c.setPadding(a.dp(20),a.dp(8),a.dp(20),a.dp(16));return c;}
    private ScrollView scroll(LinearLayout c){ScrollView s=new ScrollView(a);s.addView(c);return s;}
    private void semester(){
        LinearLayout c=form();final LocalDate[] date={model.semester};TextView pick=a.button(UiText.get("schedule_044")+date[0],false,()->{ToolDialog.prepare(new DatePickerDialog(a,(v,y,m,d)->{LocalDate selected=LocalDate.of(y,m+1,d);if(selected.getDayOfWeek()!=DayOfWeek.MONDAY){a.toast(UiText.get("schedule_045"));return;}date[0]=selected;semesterDate.setText(UiText.get("schedule_044")+selected);},date[0].getYear(),date[0].getMonthValue()-1,date[0].getDayOfMonth())).show();});semesterDate=pick;c.addView(pick);a.gap(c,14);EditText weeks=field(c,UiText.get("schedule_046"),String.valueOf(model.weeks),true);TextParagraphs.append(a,c,UiText.get("schedule_043"),13,a.MUTED);
        AlertDialog dialog=new ToolDialog(a).setTitle(UiText.get("schedule_027")).setView(c).setPositiveButton(UiText.get("action_save"),null).setNegativeButton(UiText.get("action_cancel"),null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{try{int count=Integer.parseInt(weeks.getText().toString());if(count<1||count>60)throw new Exception();for(ScheduleModel.Course x:model.courses)if(x.parity==3?!x.customWeeks.isEmpty()&&x.customWeeks.last()>count:x.weekEnd>count){a.toast(UiText.get("schedule_047")+x.weekEnd+UiText.get("schedule_048"));return;}model.semester=date[0];model.weeks=count;selectedWeek=Math.max(1,Math.min(count,model.week(LocalDate.now())));save();dialog.dismiss();a.switchTab(1);}catch(Exception e){a.toast(UiText.get("schedule_049"));}}));dialog.show();
    }
    private TextView semesterDate;
    private void times(){
        LinearLayout c=form();
        for(int i=0;i<model.slots.size();i++){final int index=i;ScheduleModel.Slot slot=model.slots.get(i);c.addView(a.button(UiText.get("schedule_model_018")+(i+1)+UiText.get("schedule_051")+slot.start+"–"+slot.end,false,()->timeEditor(index)));a.gap(c,8);}
        c.addView(a.button(UiText.get("schedule_052"),false,()->{if(model.slots.size()>=20){a.toast(UiText.get("schedule_053"));return;}timeEditor(model.slots.size());}));a.gap(c,8);
        c.addView(a.button(UiText.get("schedule_054"),false,()->{int last=model.slots.size();if(last<=1){a.toast(UiText.get("schedule_055"));return;}for(ScheduleModel.Course x:model.courses)if(x.last>=last){a.toast(UiText.get("schedule_056"));return;}new ToolDialog(a).setMessage(UiText.get("schedule_057")+last+UiText.get("schedule_058")).setPositiveButton(UiText.get("gps_092"),(d,n)->{model.slots.remove(last-1);save();timesDialog.dismiss();times();}).setNegativeButton(UiText.get("action_cancel"),null).show();}));
        a.gap(c,12);TextParagraphs.append(a,c,UiText.get("schedule_050"),13,a.MUTED);
        timesDialog=new ToolDialog(a).setTitle(UiText.get("schedule_028")).setView(scroll(c)).setNegativeButton(UiText.get("action_back"),(d,n)->a.refreshScreen()).create();timesDialog.show();
    }
    private AlertDialog timesDialog;
    private void timeEditor(int index){
        boolean adding=index==model.slots.size();String start=adding?(ScheduleModel.minute(model.slots.get(index-1).end)<=1370?LocalTime.parse(model.slots.get(index-1).end).plusMinutes(10).toString():"23:00"):model.slots.get(index).start;String end=adding?(ScheduleModel.minute(start)<=1394?LocalTime.parse(start).plusMinutes(45).toString():"23:59"):model.slots.get(index).end;final String[] values={start,end};LinearLayout c=form();TextView begin=a.button(UiText.get("schedule_059")+start,false,()->{}),finish=a.button(UiText.get("schedule_060")+end,false,()->{});begin.setOnClickListener(v->pickTime(values,0,begin,UiText.get("schedule_061")));finish.setOnClickListener(v->pickTime(values,1,finish,UiText.get("schedule_062")));c.addView(begin);a.gap(c,12);c.addView(finish);
        AlertDialog dialog=new ToolDialog(a).setTitle(UiText.get("schedule_model_018")+(index+1)+UiText.get("schedule_063")).setView(c).setPositiveButton(UiText.get("action_save"),null).setNegativeButton(UiText.get("action_cancel"),null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{String error=model.validateSlot(index,values[0],values[1]);if(error!=null){a.toast(error);return;}if(adding)model.slots.add(new ScheduleModel.Slot(values[0],values[1]));else model.slots.set(index,new ScheduleModel.Slot(values[0],values[1]));save();dialog.dismiss();timesDialog.dismiss();times();}));dialog.show();
    }
    private void pickTime(String[] values,int index,TextView view,String label){NumericInputs.time(a,LocalTime.parse(values[index]),time->{values[index]=time.toString();view.setText(label+UiText.get("earthquake_intensity_003")+values[index]);});}
    private void edit(ScheduleModel.Course old){
        if(old==null&&model.courses.size()>=300){a.toast(UiText.get("schedule_064"));return;}ScheduleModel.Course course=old==null?new ScheduleModel.Course():old.copy();if(old==null)course.weekEnd=model.weeks;
        LinearLayout c=form();EditText name=field(c,UiText.get("schedule_065"),course.name,false),room=field(c,UiText.get("schedule_066"),course.room,false),teacher=field(c,UiText.get("schedule_067"),course.teacher,false);Spinner day=spinner(c,UiText.get("schedule_068"),days(),course.day-1);
        String[] periods=new String[model.slots.size()];for(int i=0;i<periods.length;i++)periods[i]=UiText.get("schedule_model_018")+(i+1)+UiText.get("schedule_018")+model.slots.get(i).start+"–"+model.slots.get(i).end;
        Spinner first=spinner(c,UiText.get("schedule_069"),periods,course.first-1),last=spinner(c,UiText.get("schedule_070"),periods,course.last-1);
        Spinner parity=spinner(c,UiText.get("schedule_071"),new String[]{UiText.get("schedule_072"),UiText.get("schedule_073"),UiText.get("schedule_074"),UiText.get("schedule_075")},course.parity);
        LinearLayout range=a.column();EditText weekStart=field(range,UiText.get("schedule_076"),String.valueOf(course.weekStart),true),weekEnd=field(range,UiText.get("schedule_077"),String.valueOf(course.weekEnd),true);c.addView(range);
        TextView custom=a.button(UiText.get("schedule_078"),false,()->{});custom.setText(UiText.get("schedule_079")+(course.customWeeks.isEmpty()?UiText.get("schedule_080"):ScheduleModel.customLabel(course.customWeeks)));custom.setOnClickListener(v->{String[] labels=new String[model.weeks];boolean[] chosen=new boolean[model.weeks];for(int i=0;i<labels.length;i++){labels[i]=UiText.get("schedule_model_018")+(i+1)+UiText.get("schedule_model_017");chosen[i]=course.customWeeks.contains(i+1);}new ToolDialog(a).setTitle(UiText.get("schedule_081")).setMultiChoiceItems(labels,chosen,(d,n,on)->chosen[n]=on).setPositiveButton(UiText.get("numeric_inputs_004"),(d,n)->{course.customWeeks.clear();for(int i=0;i<chosen.length;i++)if(chosen[i])course.customWeeks.add(i+1);custom.setText(UiText.get("schedule_079")+(course.customWeeks.isEmpty()?UiText.get("schedule_080"):ScheduleModel.customLabel(course.customWeeks)));}).setNegativeButton(UiText.get("action_cancel"),null).show();});c.addView(custom);a.gap(c,12);
        Runnable visibility=()->{boolean own=parity.getSelectedItemPosition()==3;range.setVisibility(own?View.GONE:View.VISIBLE);custom.setVisibility(own?View.VISIBLE:View.GONE);};visibility.run();parity.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int n,long id){visibility.run();}});
        TextView color=a.button(a.getString(R.string.course_color,ColorPicker.name(a,course.seedColor())),false,()->{});color.setOnClickListener(v->ColorPicker.show(a,a.getString(R.string.course_color_title),course.seedColor(),value->{course.colorHex=ThemeColors.hex(value);color.setText(a.getString(R.string.course_color,ColorPicker.name(a,value)));}));c.addView(color);a.gap(c,12);
        AlertDialog.Builder b=new ToolDialog(a).setTitle(old==null?UiText.get("action_add_course"):UiText.get("schedule_082")).setView(scroll(c)).setPositiveButton(UiText.get("action_save"),null).setNegativeButton(UiText.get("action_cancel"),null);if(old!=null)b.setNeutralButton(UiText.get("gps_092"),null);AlertDialog dialog=b.create();dialog.setOnShowListener(d->{dialog.getButton(-1).setOnClickListener(v->{try{course.name=name.getText().toString().trim();course.room=room.getText().toString().trim();course.teacher=teacher.getText().toString().trim();course.day=day.getSelectedItemPosition()+1;course.first=first.getSelectedItemPosition()+1;course.last=last.getSelectedItemPosition()+1;course.parity=parity.getSelectedItemPosition();if(course.parity==3){if(course.customWeeks.isEmpty()){a.toast(UiText.get("schedule_083"));return;}course.weekStart=course.customWeeks.first();course.weekEnd=course.customWeeks.last();}else{course.weekStart=Integer.parseInt(weekStart.getText().toString());course.weekEnd=Integer.parseInt(weekEnd.getText().toString());}String error=model.validateCourse(course);if(error!=null){a.toast(error);return;}model.put(course);save();dialog.dismiss();a.switchTab(1);}catch(Exception e){a.toast(UiText.get("schedule_084"));}});if(old!=null)dialog.getButton(-3).setOnClickListener(v->new ToolDialog(a).setTitle(UiText.get("schedule_085")).setMessage(UiText.get("schedule_086")+old.name+UiText.get("schedule_087")).setPositiveButton(UiText.get("gps_092"),(x,n)->{model.courses.removeIf(y->y.id.equals(old.id));save();dialog.dismiss();a.switchTab(1);}).setNegativeButton(UiText.get("action_cancel"),null).show());});dialog.show();
    }
}
